import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Actions & Instant Preview","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Action Menu Deep Dive","slug":"_1-action-menu-deep-dive","link":"#_1-action-menu-deep-dive","children":[{"level":3,"title":"Built-in Core Actions Cheat Sheet","slug":"built-in-core-actions-cheat-sheet","link":"#built-in-core-actions-cheat-sheet","children":[]},{"level":3,"title":"Action Menu Interaction & Filtering","slug":"action-menu-interaction-filtering","link":"#action-menu-interaction-filtering","children":[]}]},{"level":2,"title":"2. Full Window Results List Features","slug":"_2-full-window-results-list-features","link":"#_2-full-window-results-list-features","children":[]},{"level":2,"title":"3. Built-in QuickLook Instant Preview","slug":"_3-built-in-quicklook-instant-preview","link":"#_3-built-in-quicklook-instant-preview","children":[{"level":3,"title":"Preview Has No Keyboard","slug":"preview-has-no-keyboard","link":"#preview-has-no-keyboard","children":[]},{"level":3,"title":"Supported Formats & Rich Capabilities","slug":"supported-formats-rich-capabilities","link":"#supported-formats-rich-capabilities","children":[]},{"level":3,"title":"Adaptive Layout & Pop-up Handling","slug":"adaptive-layout-pop-up-handling","link":"#adaptive-layout-pop-up-handling","children":[]}]},{"level":2,"title":"4. Plugin Interactive & Rich Text Previews","slug":"_4-plugin-interactive-rich-text-previews","link":"#_4-plugin-interactive-rich-text-previews","children":[]},{"level":2,"title":"5. Third-party QuickLook Bridge (Optional)","slug":"_5-third-party-quicklook-bridge-optional","link":"#_5-third-party-quicklook-bridge-optional","children":[]},{"level":2,"title":"6. Release File Occupation","slug":"_6-release-file-occupation","link":"#_6-release-file-occupation","children":[]},{"level":2,"title":"7. Add to Favorites","slug":"_7-add-to-favorites","link":"#_7-add-to-favorites","children":[]},{"level":2,"title":"8. Rename","slug":"_8-rename","link":"#_8-rename","children":[]}],"relativePath":"user-guide/actions-and-preview.md","filePath":"user-guide/actions-and-preview.md","lastUpdated":1791112464000}'),a={name:"user-guide/actions-and-preview.md"};function r(l,e,s,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="actions-instant-preview" tabindex="-1">Actions &amp; Instant Preview <a class="header-anchor" href="#actions-instant-preview" aria-label="Permalink to &quot;Actions &amp; Instant Preview&quot;">​</a></h1><p>Lertaro locates files and integrates a context action system and an instant preview panel, letting you inspect, manage, and dispatch files without constantly switching to File Explorer.</p><h2 id="_1-action-menu-deep-dive" tabindex="-1">1. Action Menu Deep Dive <a class="header-anchor" href="#_1-action-menu-deep-dive" aria-label="Permalink to &quot;1. Action Menu Deep Dive&quot;">​</a></h2><p>In the Quick Window, press <code>Ctrl+O</code> or <code>→</code> on the highlighted result to expand the contextual action menu — <code>→</code> only when the caret is already at the end of the query, so it never hijacks cursor movement while you are editing earlier in the text. The same keys work in the inline card <strong>outside</strong> file dialogs; a card docked in an Open/Save/Browse dialog has no action menu at all. In the Full Search Window neither key is wired: right-click a result, or press <code>Apps</code> (<code>Shift+F10</code>), to open the same menu there.</p><p>Not every row has a menu. It is withheld from the <strong>Show More</strong> row, plugin-provided results, web-link favorites, instant results that no provider claims, applications outside the Quick Window, and every file dialog — on such a row the menu keys do nothing instead of opening an empty panel.</p><h3 id="built-in-core-actions-cheat-sheet" tabindex="-1">Built-in Core Actions Cheat Sheet <a class="header-anchor" href="#built-in-core-actions-cheat-sheet" aria-label="Permalink to &quot;Built-in Core Actions Cheat Sheet&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Default Hotkey</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Open</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Opens the selected item or launches the application with the system default program. In the Full Search Window, <code>Enter</code> acts on <strong>every</strong> selected row; double-click opens only the row you double-clicked.</td></tr><tr><td style="text-align:left;"><strong>Reveal in Explorer</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Opens the parent directory and highlights the item in Windows File Explorer.</td></tr><tr><td style="text-align:left;"><strong>Run as Administrator</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Launches the selected application or script with elevated administrative permissions.</td></tr><tr><td style="text-align:left;"><strong>Copy Full Path</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">Copies the absolute path (e.g. <code>D:\\Projects\\app.exe</code>) to the clipboard.</td></tr><tr><td style="text-align:left;"><strong>Copy Name</strong></td><td style="text-align:left;"><code>Shift+C</code></td><td style="text-align:left;">Copies the names of the selected files or folders to the clipboard, without their paths.</td></tr><tr><td style="text-align:left;"><strong>Copy File</strong></td><td style="text-align:left;"><code>Ctrl+C</code></td><td style="text-align:left;">Places the file itself on the clipboard, ready to paste into Explorer or any folder.</td></tr><tr><td style="text-align:left;"><strong>Cut / Copy File</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">Places the file itself on the clipboard, ready to paste into Explorer or any folder. With text selected in the search box these stay text commands.</td></tr><tr><td style="text-align:left;"><strong>Paste into Folder</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">When a folder is highlighted, pastes clipboard files directly into that directory; when a file is highlighted, pastes into its parent folder. Needs a real file list on the clipboard, so pasting text into the query is unaffected.</td></tr><tr><td style="text-align:left;"><strong>Delete (Recycle Bin)</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">Safely moves the selected file or directory to the Windows Recycle Bin. A bare key only reaches the action when the caret is already at the end of the query, and the native Recycle Bin confirmation follows.</td></tr><tr><td style="text-align:left;"><strong>Permanent Delete</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">Permanently deletes the selected item (native &quot;permanently delete?&quot; prompt; after that it cannot be recovered).</td></tr><tr><td style="text-align:left;"><strong>Rename</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Renames one existing file or folder through the Windows Shell. The dialog preselects the filename portion for convenient replacement.</td></tr><tr><td style="text-align:left;"><strong>Windows Context Menu</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Expands the full native Windows Explorer context menu with third-party extensions and &quot;Send to&quot;.</td></tr></tbody></table><h3 id="action-menu-interaction-filtering" tabindex="-1">Action Menu Interaction &amp; Filtering <a class="header-anchor" href="#action-menu-interaction-filtering" aria-label="Permalink to &quot;Action Menu Interaction &amp; Filtering&quot;">​</a></h3><ul><li><strong>Type to Filter</strong>: Once the action menu opens, type immediately to filter actions by name (e.g., typing <code>copy</code> narrows the list to copy-related actions). The filter box takes the keyboard, so navigating away never touches your original query.</li><li><strong>Mnemonic Letters</strong>: Every action may show a highlighted letter. Pressing it <strong>runs the action at once</strong> — it does not merely highlight it — but only while the filter box is still empty, so the first letter you type for a filter is never stolen.</li><li><strong>Independent Search Box</strong>: The action menu has its own focused search box, so filtering actions never changes the main search query. Moving to another menu level clears the action filter and focuses the new level&#39;s search box.</li><li><strong>Floating Action Panel</strong>: In the Quick Window, Quick Launch panel, and Full Search Window, actions appear in a floating panel anchored to the active result. The Quick Launch panel expands to the action menu&#39;s full working height and returns to its compact height when the menu closes.</li><li><strong>Hierarchical Navigation</strong>: On items with submenus (such as &quot;Send to&quot;), press <code>→</code>, <code>Tab</code> or <code>Enter</code> to enter; press <code>←</code> or <code>Backspace</code> (when filter text is empty) to return to the parent level. In a nested menu, <code>Escape</code> and right-click return to the parent; at the root level they close the action menu.</li><li><strong>Navigation Keys Still Work</strong>: Your configured Next/Previous Item hotkeys (<code>Ctrl+N</code> / <code>Ctrl+P</code> by default) move the highlight inside the action list too, wrapping past the first and last entry and skipping separators, headers and disabled actions. <code>Tab</code> only enters a submenu when you have not bound it to one of those keys.</li><li><strong>Click Away to Close</strong>: Clicking outside a floating action panel closes it. Right-clicking another result replaces the current action target in place when the host supports it.</li><li><strong>Action Hotkeys</strong>: Provider-defined action shortcuts work while the action panel is focused. Executing one closes the floating panel while keeping the Full Search Window or Quick Launch panel open.</li></ul><h2 id="_2-full-window-results-list-features" tabindex="-1">2. Full Window Results List Features <a class="header-anchor" href="#_2-full-window-results-list-features" aria-label="Permalink to &quot;2. Full Window Results List Features&quot;">​</a></h2><p>The Full Search Window (<code>Ctrl+F</code>) is designed for high-density file management and exploration:</p><ul><li><strong>Double-click Path Column</strong>: Double-clicking the <strong>Name</strong> column opens the file; double-clicking the <strong>Path</strong> column opens the containing parent folder directly. Double-click means the <em>left</em> button only; double-clicking a column header does nothing, and maximize/restore is the double-click on the window&#39;s top non-input band.</li><li><strong>Multi-Selection</strong>: The grid is a normal Windows list — <code>Ctrl</code>+click adds or removes rows, <code>Shift</code>+click takes a range, and <code>Enter</code> then acts on <strong>all</strong> selected rows at once, while a double-click opens only the row you double-clicked. Right-clicking a row that is already part of a selection keeps the whole selection instead of collapsing it to that one row.</li><li><strong>Infinite Streaming Results</strong>: When scanning millions of items, results stream into the view incrementally without waiting for the full index scan to conclude. You can interact with rows immediately as they arrive, and appending new rows keeps your selection and scroll position; a genuinely new result set starts again from the top.</li><li><strong>Wrap-around Navigation</strong>: Pressing <code>↑</code> on the top row wraps around to the last item; pressing <code>↓</code> on the bottom row wraps back to the first. The same wrap applies in the Quick Window and the inline card — pressing <code>↑</code> with nothing selected yet lands on the last row, <code>↓</code> on the first. Only the Quick Panel walks its groups as one continuous list <strong>without</strong> wrapping.</li><li><strong>Horizontal Scrolling</strong>: <code>Shift</code> + mouse wheel over the grid scrolls three columns per notch, which is how you reach the far columns on a narrow window.</li><li><strong>Drag Files Out</strong>: Any row can be dragged straight into Explorer, a dialog, or a chat window as a real file drop; with a multi-selection, dragging one of its members carries <strong>all</strong> of them. Dropping outside Lertaro hides the window, and the close is held back while a drag is in flight so the drag cursor cannot stick.</li><li><strong>Selection Summary</strong>: When multiple rows are selected, the status bar shows the selected item count next to the total result count.</li><li><strong>Hover Previews</strong>: Moving the pointer over a row retargets an already-open preview panel without changing the selection, so you can flip through candidates and press <code>Enter</code> on the row you came back to.</li><li><strong>Window Dragging &amp; Size Memory</strong>: Drag the non-interactive top area of the window to reposition it; manually resized dimensions are automatically remembered across sessions.</li></ul><h2 id="_3-built-in-quicklook-instant-preview" tabindex="-1">3. Built-in QuickLook Instant Preview <a class="header-anchor" href="#_3-built-in-quicklook-instant-preview" aria-label="Permalink to &quot;3. Built-in QuickLook Instant Preview&quot;">​</a></h2><p>Press <code>Alt+P</code> on a previewable result to summon the docked preview panel alongside the search window — or <strong>middle-click the row</strong>, which toggles the same panel. Neither gesture is available in the inline window; the Quick Panel supports both.</p><h3 id="preview-has-no-keyboard" tabindex="-1">Preview Has No Keyboard <a class="header-anchor" href="#preview-has-no-keyboard" aria-label="Permalink to &quot;Preview Has No Keyboard&quot;">​</a></h3><p>The panel is deliberately non-activating: it never takes focus from the search window, so there is nothing to type into and <code>Escape</code> does not close it. Toggle it with <code>Alt+P</code> or hide it by closing the window it is docked to. All its controls — the media playback bar, scrollbars, plugin cards — are mouse-only, and keyboard focus stays exactly where it was.</p><h3 id="supported-formats-rich-capabilities" tabindex="-1">Supported Formats &amp; Rich Capabilities <a class="header-anchor" href="#supported-formats-rich-capabilities" aria-label="Permalink to &quot;Supported Formats &amp; Rich Capabilities&quot;">​</a></h3><ul><li><strong>Images</strong>: Scaling render for JPG, PNG, GIF, BMP, and ICO images.</li><li><strong>Text &amp; Code</strong>: Plain monospaced rendering for TXT, Markdown, JSON, XML, YAML, C#, Python, JS, HTML, etc. (no syntax highlighting).</li><li><strong>Audio &amp; Video Playback</strong>: Video files (MP4, M4V, WMV, AVI, MOV, MPG/MPEG) and audio files (MP3, WAV, WMA, M4A, AAC) <strong>auto-play immediately</strong> with a theme-aware mini playback bar (play/pause, progress scrubbing, duration, mute). Playback stops instantly when switching items.</li><li><strong>Folder Structural Inspection</strong>: Shows up to 30 direct child items with file icons and sizes, automatically filtering system and hidden files.</li></ul><h3 id="adaptive-layout-pop-up-handling" tabindex="-1">Adaptive Layout &amp; Pop-up Handling <a class="header-anchor" href="#adaptive-layout-pop-up-handling" aria-label="Permalink to &quot;Adaptive Layout &amp; Pop-up Handling&quot;">​</a></h3><ul><li><strong>Adaptive Screen Bounds</strong>: Preview dimensions can be customized under <a href="./settings/general.html#_4-preview-window"><strong>Settings → General → Preview</strong></a>; Lertaro guarantees the panel remains within the visible monitor bounds.</li><li><strong>Docking Side</strong>: The panel docks to the <strong>right</strong> of its search window and flips to the left only when the right cannot fit it — it does not chase the roomier side, so it stays put while you scroll a wide window. It then follows the owner as you move or resize that window.</li><li><strong>Resize Memory Is Per Session</strong>: Dragging the resize grip or moving the panel is remembered while the preview stays in play, but the next time the search window is hidden or closed the panel returns to the configured size and docking side.</li><li><strong>Native Dialog Avoidance</strong>: When previewing password-protected Office documents, Lertaro temporarily hides both windows so the native password dialog can be interacted with, and restores them afterwards.</li><li><strong>Drag Source</strong>: The top area of the preview panel acts as a drag source — drag the previewed file directly into editors, browsers, or chat applications. The footer bar drags the panel itself.</li></ul><h2 id="_4-plugin-interactive-rich-text-previews" tabindex="-1">4. Plugin Interactive &amp; Rich Text Previews <a class="header-anchor" href="#_4-plugin-interactive-rich-text-previews" aria-label="Permalink to &quot;4. Plugin Interactive &amp; Rich Text Previews&quot;">​</a></h2><p>QuickLook supports custom interactive preview cards provided by plugins:</p><ul><li><strong>Theme-Adaptive Rich Text</strong>: Rendered via modern WebView2 and native controls, automatically matching dark/light system themes with high-contrast typography and subtle translucent scrollbars.</li><li><strong>Interactive Plugin Cards</strong>: MDict dictionary lookups, live weather forecasts, instant webpage snapshots, and API debugging payloads.</li></ul><h2 id="_5-third-party-quicklook-bridge-optional" tabindex="-1">5. Third-party QuickLook Bridge (Optional) <a class="header-anchor" href="#_5-third-party-quicklook-bridge-optional" aria-label="Permalink to &quot;5. Third-party QuickLook Bridge (Optional)&quot;">​</a></h2><p>If you have installed the standalone open-source tool <strong>QuickLook</strong> (<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">QL-Win/QuickLook on GitHub</a>), enable the <strong>QuickLook Bridge</strong> plugin under <a href="./settings/plugins.html"><strong>Settings → Plugins</strong></a>.</p><ul><li><strong>External Preview Takeover</strong>: Connects via local named pipes to host external QuickLook preview windows anchored directly beside Lertaro.</li><li><strong>Automatic Fallback</strong>: If the external QuickLook process is not running, Lertaro falls back to its built-in preview engine.</li></ul><h2 id="_6-release-file-occupation" tabindex="-1">6. Release File Occupation <a class="header-anchor" href="#_6-release-file-occupation" aria-label="Permalink to &quot;6. Release File Occupation&quot;">​</a></h2><p>The official <strong>File Occupation Release</strong> plugin adds a single-selection action for existing files. It lists the processes currently using the file, including their PIDs and executable paths, and sends a request for those processes to release it. The action is disabled for folders, missing files, or multiple selections; the release button is also disabled when no process is detected. The themed dialog supports refresh and automatically hides itself from Alt+Tab while remaining above the search window.</p><h2 id="_7-add-to-favorites" tabindex="-1">7. Add to Favorites <a class="header-anchor" href="#_7-add-to-favorites" aria-label="Permalink to &quot;7. Add to Favorites&quot;">​</a></h2><p>CoreExtensions provides an <strong>Add to Favorites</strong> action for one existing file or folder. It opens a themed dialog for the display name and hides the action when the same path is already a favorite.</p><h2 id="_8-rename" tabindex="-1">8. Rename <a class="header-anchor" href="#_8-rename" aria-label="Permalink to &quot;8. Rename&quot;">​</a></h2><p>CoreExtensions provides a <strong>Rename</strong> action for one existing file or folder. The themed dialog shows the full current name and preselects the filename portion: for <code>report.pdf</code>, only <code>report</code> is selected, while folders and names without an extension are selected in full. Press <code>Enter</code> to confirm or <code>Esc</code> to cancel. After confirmation, the actual rename is delegated to the Windows Shell.</p>',32)])])}const p=t(a,[["render",r]]);export{u as __pageData,p as default};
